import fs from "node:fs";
const files=[
 "packages/tax-open/src/SimulatorSubmissionPackageService.ts",
 "docs/TAX_SIMULATOR_SUBMISSION_RC4.md"
];
for(const file of files){if(!fs.existsSync(file))throw new Error(`Missing ${file}`)}
const service=fs.readFileSync(files[0],"utf8");
for(const token of ["SIMULATOR-SUBMISSION.zip","SUBMISSION-MANIFEST.json","README-SIMULATOR.txt","SIMULATOR-RESULTS","sha256"]){if(!service.includes(token))throw new Error(`Missing token ${token}`)}
console.log("✓ Tax simulator submission package structure verified");

